// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 _value, uint8 extraDeposits) public {
        vm.assume(_value < type(uint104).max);
        vm.assume(extraDeposits < 100);
        for (uint i = 0; i < extraDeposits; i++) {
            (bool s,) = address(c).call{value: 1}('');
            require(s);
        }
        uint balanceBefore = address(c).balance;
        vm.assume(_value <= balanceBefore);
        Helper helper = new Helper();
        c.sendMoney(address(helper), _value, '');
        uint balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore - _value);
    }
}

contract Helper {
    fallback() external payable {}
}
